"""Northbridge rating policy (rating-policy-v1.0).

Deterministic implementation of the group's applicability-and-impact policy.
The model gathers facts with tools and records its judgments (condition
results, reachability, criticality, blast radius). This module turns those
facts into scores, a rating and a policy rule. The model never picks the
rating itself.

Gate 1 - Applicability (C1 affected OS, C2 DNS Server installed, C3 build
below fixed build). Precedence when several outcomes are possible:
    1. any condition "false"       -> P-NA  (Low, Not Applicable)
    2. decisive tool failure       -> P-RV-F (Review Needed)
    3. any condition "conflicting" -> P-RV-C (Review Needed)
    4. any condition "unknown"     -> P-IE  (Insufficient Evidence)
    5. all "true"                  -> Gate 2
A confirmed "false" wins because one missing prerequisite is enough to show
the vulnerability is not present. The design doc lists the outcomes but not
their precedence; this order is the group's choice.

Gate 2 - Likelihood (sum, 0-6) x Impact (max, 0-2) -> rating matrix.
When Gate 1 ends in P-IE and Gate 2 inputs are available, Gate 2 is also
computed as a non-binding provisional rating for prioritization.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Optional

POLICY_VERSION = "rating-policy-v1.0"

CONDITION_VALUES = {"true", "false", "unknown", "conflicting"}
LEVEL_CODE = {"Low": "L", "Medium": "M", "High": "H"}
IMPACT_LEVELS = ["Low", "Medium", "High"]

# Rows: likelihood level, columns: impact level.
MATRIX = {
    "Low": {"Low": "Low", "Medium": "Low", "High": "Medium"},
    "Medium": {"Low": "Low", "Medium": "Medium", "High": "High"},
    "High": {"Low": "Medium", "Medium": "High", "High": "High"},
}


@dataclass
class PolicyInputs:
    """Facts the agent gathered. None means unknown."""

    conditions: dict[str, str]                  # {"C1": "true", "C2": "true", "C3": "unknown"}
    decisive_tool_failure: bool = False         # lookup_vulnerability or environment_search failed, no cache

    # Likelihood
    reachability: Optional[int] = None          # 0 isolated, 1 broad internal, 2 Internet-facing; None -> default 1
    cvss_metrics: Optional[dict[str, str]] = None  # {"AV": "N", "AC": "L", "PR": "N", "UI": "N", "C": "H", "I": "H", "A": "H"}
    kev_listed: Optional[bool] = None
    credible_in_the_wild: Optional[bool] = None
    public_poc: Optional[bool] = None
    vendor_exploitation_likely: Optional[bool] = None

    # Impact
    asset_criticality: Optional[int] = None     # 0 non-critical, 1 business-important, 2 critical
    blast_radius: Optional[int] = None          # 0 single host, 1 service/department, 2 domain/organization
    rto_hours: Optional[float] = None

    def __post_init__(self) -> None:
        for cid, val in self.conditions.items():
            if val not in CONDITION_VALUES:
                raise ValueError(f"{cid}: '{val}' is not one of {sorted(CONDITION_VALUES)}")
        for name in ("reachability", "asset_criticality", "blast_radius"):
            val = getattr(self, name)
            if val is not None and val not in (0, 1, 2):
                raise ValueError(f"{name} must be 0, 1, 2 or None, got {val!r}")


# ---------------------------------------------------------------- Gate 1

def gate_1(inp: PolicyInputs) -> tuple[str, str]:
    """Return (applicability_status, gate_1_outcome)."""
    values = set(inp.conditions.values())
    if "false" in values:
        return "Not Applicable", "P-NA"
    if inp.decisive_tool_failure:
        return "Unknown", "P-RV-F"
    if "conflicting" in values:
        return "Conflicting", "P-RV-C"
    if "unknown" in values:
        return "Unknown", "P-IE"
    return "Confirmed", "Gate 2"


# ---------------------------------------------------------------- Gate 2

def exploitability_score(m: dict[str, str]) -> int:
    if m.get("AV") in ("L", "P"):
        return 0
    if m.get("AV") in ("N", "A") and m.get("AC") == "L" and m.get("PR") == "N" and m.get("UI") == "N":
        return 2
    if m.get("AV") in ("N", "A"):
        return 1
    raise ValueError(f"Cannot score exploitability from CVSS metrics {m}")


def exploit_activity_score(inp: PolicyInputs) -> int:
    if inp.kev_listed or inp.credible_in_the_wild:
        return 2
    if inp.public_poc or inp.vendor_exploitation_likely:
        return 1
    return 0


def likelihood_level(score: int) -> str:
    return "Low" if score <= 2 else "Medium" if score <= 4 else "High"


def gate_2_available(inp: PolicyInputs) -> bool:
    return inp.cvss_metrics is not None and inp.asset_criticality is not None and inp.blast_radius is not None


def likelihood(inp: PolicyInputs) -> dict:
    defaulted = inp.reachability is None
    reach = 1 if defaulted else inp.reachability
    expl = exploitability_score(inp.cvss_metrics)
    act = exploit_activity_score(inp)
    raw = reach + expl + act
    cap = reach == 0
    final = min(raw, 1) if cap else raw
    return {
        "factors": {
            "reachability": {"score": reach, "defaulted": defaulted},
            "exploitability": {"score": expl},
            "exploit_activity": {"score": act},
        },
        "raw_sum": raw,
        "reachability_cap_applied": cap,
        "final_score": final,
        "level": likelihood_level(final),
    }


def _clamp(x: int) -> int:
    return max(0, min(2, x))


def impact(inp: PolicyInputs) -> dict:
    base = max(inp.asset_criticality, inp.blast_radius)
    m = inp.cvss_metrics

    rto_known = inp.rto_hours is not None
    rto_trig = rto_known and inp.rto_hours <= 4
    cia_trig = all(m.get(k) in ("L", "N") for k in ("C", "I", "A"))
    effects = {"ADJ-RTO": 1 if rto_trig else 0, "ADJ-CIA": -1 if cia_trig else 0}

    final = _clamp(base + sum(effects.values()))
    adjustments = []
    for adj_id, triggered, status, value in (
        ("ADJ-RTO", rto_trig, "known" if rto_known else "unknown", inp.rto_hours),
        ("ADJ-CIA", cia_trig, "known", f"C:{m.get('C')}/I:{m.get('I')}/A:{m.get('A')}"),
    ):
        without = _clamp(base + sum(v for k, v in effects.items() if k != adj_id))
        adjustments.append({
            "id": adj_id,
            "input_value": value,
            "input_status": status,
            "triggered": triggered,
            "effect": effects[adj_id],
            "binding": without != final,
        })
    return {
        "factors": {
            "asset_criticality": {"score": inp.asset_criticality},
            "blast_radius": {"score": inp.blast_radius},
        },
        "base_score": base,
        "adjustments": adjustments,
        "final_score": final,
        "level": IMPACT_LEVELS[final],
    }


def matrix(lk: dict, im: dict) -> dict:
    rating = MATRIX[lk["level"]][im["level"]]
    return {
        "likelihood_level": lk["level"],
        "impact_level": im["level"],
        "rating": rating,
        "policy_rule": f"P-{LEVEL_CODE[rating]}-L{lk['final_score']}I{im['final_score']}",
    }


# ---------------------------------------------------------------- Entry point

def evaluate(inp: PolicyInputs) -> dict:
    """Apply the full policy. Returns the decision and the scored rationale blocks."""
    status, outcome = gate_1(inp)

    lk = im = mx = None
    if outcome in ("Gate 2", "P-IE") and gate_2_available(inp):
        lk, im = likelihood(inp), impact(inp)
        mx = matrix(lk, im)
    elif outcome == "Gate 2":
        raise ValueError("Applicability confirmed but Gate 2 inputs (CVSS metrics, criticality, blast radius) are missing")

    if outcome == "Gate 2":
        decision = {"rating": mx["rating"], "policy_rule_applied": mx["policy_rule"], "gate_reached": "Gate 2", "provisional": None}
        gate_2_status = "evaluated"
    else:
        rating = {"P-NA": "Low", "P-IE": "Insufficient Evidence"}.get(outcome, "Review Needed")
        provisional = None
        if outcome == "P-IE" and mx:
            provisional = {"rating": mx["rating"], "policy_rule": mx["policy_rule"], "binding": False}
        decision = {"rating": rating, "policy_rule_applied": outcome, "gate_reached": "Gate 1", "provisional": provisional}
        gate_2_status = "provisional" if provisional else "not_evaluated"
        if not provisional:
            lk = im = mx = None

    return {
        "policy_version": POLICY_VERSION,
        "decision": decision,
        "applicability": {"status": status, "gate_1_outcome": outcome},
        "gate_2_status": gate_2_status,
        "likelihood": lk,
        "impact": im,
        "matrix_result": mx,
    }


def parse_cvss_vector(vector: str) -> dict[str, str]:
    """'CVSS:3.1/AV:N/AC:L/...' -> {'AV': 'N', 'AC': 'L', ...}"""
    parts = [p.split(":", 1) for p in vector.split("/") if ":" in p]
    return {k: v for k, v in parts if k != "CVSS"}

"""Validate an assessment JSON.

1. Structure: JSON Schema (assessment_schema.json) - fields, types, allowed values.
2. Consistency: cross-field rules the schema does not express - evidence references,
   source labeling, tool-contract rules, and agreement with policy.py.

Usage:
    python validate.py assessment.json [--schema assessment_schema.json] [--write]

--write stores the check results in the assessment's "validation" block.
Exit code 0 when every check passes, 1 otherwise.
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

import jsonschema

from policy import PolicyInputs, evaluate, parse_cvss_vector

HERE = Path(__file__).resolve().parent
DEFAULT_SCHEMA = HERE / "assessment_schema.json"

ENV_QUERY_TYPES = {"asset", "text", "flows", "business_service"}
CVE_RE = re.compile(r"^CVE-\d{4}-\d{4,}$")
EVIDENCE_ID_RE = re.compile(r'"(E\d+)"')
DECISIVE_TOOLS = {"lookup_vulnerability", "environment_search"}


def _check(results: list, name: str, problems: list[str]) -> None:
    results.append({"check": name, "passed": not problems, "detail": "; ".join(problems) or "ok"})


# ------------------------------------------------------------------ structure

def check_schema(a: dict, schema: dict) -> list[str]:
    v = jsonschema.Draft202012Validator(schema)
    return [f"{'/'.join(map(str, e.absolute_path)) or '(root)'}: {e.message}" for e in v.iter_errors(a)]


# ------------------------------------------------------------------ references

def check_evidence_refs(a: dict) -> list[str]:
    ids = [e["evidence_id"] for e in a.get("evidence", [])]
    problems = [f"duplicate evidence_id {i}" for i in set(ids) if ids.count(i) > 1]
    body = json.dumps({k: v for k, v in a.items() if k not in ("evidence", "validation")})
    cited = set(EVIDENCE_ID_RE.findall(body))
    problems += [f"{i} cited but not in evidence[]" for i in sorted(cited - set(ids))]
    problems += [f"{i} in evidence[] but never cited" for i in sorted(set(ids) - cited)]
    return problems


def check_tool_refs(a: dict) -> list[str]:
    calls = {t["call_id"] for t in a.get("tool_trace", [])}
    return [f"{e['evidence_id']} points to unknown tool call {e['tool_call_id']}"
            for e in a.get("evidence", []) if e.get("tool_call_id") not in calls]


def check_unknown_refs(a: dict) -> list[str]:
    unknowns = {u["id"]: u for u in a.get("unknowns", [])}
    problems = []
    for uid in a["decision"].get("missing_decisive_facts") or []:
        if uid not in unknowns:
            problems.append(f"missing_decisive_facts lists {uid}, which is not in unknowns[]")
        elif not unknowns[uid]["decisive"]:
            problems.append(f"{uid} is listed as a missing decisive fact but unknowns[].decisive is false")
    if a["decision"]["policy_rule_applied"] == "P-IE" and not a["decision"].get("missing_decisive_facts"):
        problems.append("P-IE requires at least one entry in missing_decisive_facts")
    return problems


# ------------------------------------------------------------------ labeling

def check_labels(a: dict) -> list[str]:
    problems = []
    for e in a.get("evidence", []):
        if e["retrieval_mode"] == "cached" and not e.get("fallback_reason"):
            problems.append(f"{e['evidence_id']} is cached but has no fallback_reason")
        if e["source_type"] == "environment_snapshot" and e["retrieval_mode"] != "simulated":
            problems.append(f"{e['evidence_id']} comes from the environment but is not labeled simulated")
    return problems


# ------------------------------------------------------------------ tool contracts

def check_tool_contracts(a: dict) -> list[str]:
    problems = []
    invalid_counts: dict[str, int] = {}
    for t in a.get("tool_trace", []):
        cid, tool, args, status = t["call_id"], t["tool"], t["arguments"], t["result_status"]
        if status in ("failed", "invalid_request") and not t.get("error"):
            problems.append(f"{cid}: {status} without an error message")
        if status == "invalid_request":
            invalid_counts[tool] = invalid_counts.get(tool, 0) + 1
            if t["evidence_ids"]:
                problems.append(f"{cid}: an invalid request cannot produce evidence")
            continue
        if tool == "environment_search":
            if args.get("query_type") not in ENV_QUERY_TYPES:
                problems.append(f"{cid}: query_type must be one of {sorted(ENV_QUERY_TYPES)}")
            if not args.get("query"):
                problems.append(f"{cid}: environment_search requires a non-empty query")
            if t["mode"] not in ("simulated", None):
                problems.append(f"{cid}: environment_search mode must be simulated")
        elif tool == "tavily_search":
            for k in ("query", "allowed_domains", "max_results"):
                if k not in args:
                    problems.append(f"{cid}: tavily_search missing argument {k}")
            if t["mode"] not in ("live", None) or t["fallback_used"]:
                problems.append(f"{cid}: tavily_search is live only with no fallback")
        elif tool in ("lookup_kev", "lookup_vulnerability"):
            if not CVE_RE.match(str(args.get("cve_id", ""))):
                problems.append(f"{cid}: invalid cve_id {args.get('cve_id')!r}")
    for tool, n in invalid_counts.items():
        if n > 1:
            problems.append(f"{tool}: {n} invalid requests; only one correction attempt is allowed")
    return problems


def check_kev_matches_tool(a: dict) -> list[str]:
    lk = a["rationale"].get("likelihood")
    if not lk:
        return []
    recorded = lk["factors"]["exploit_activity"]["kev_listed"]
    kev_calls = [t for t in a["tool_trace"] if t["tool"] == "lookup_kev" and t["result_status"] in ("found", "not_found")]
    if not kev_calls:
        return [] if recorded is None else ["kev_listed is set but no successful lookup_kev call exists"]
    expected = kev_calls[-1]["result_status"] == "found"
    return [] if recorded == expected else [f"kev_listed is {recorded} but lookup_kev returned {kev_calls[-1]['result_status']}"]


def check_conflicts(a: dict) -> list[str]:
    if a["decision"]["policy_rule_applied"] == "P-RV-C" and not a.get("conflicts"):
        return ["P-RV-C requires at least one entry in conflicts[]"]
    return []


def check_cvss_consistency(a: dict) -> list[str]:
    lk = a["rationale"].get("likelihood")
    vector = a["severity_vs_local_risk"]["technical_severity"].get("vector")
    if not lk or not vector:
        return []
    m = parse_cvss_vector(vector)
    ex = lk["factors"]["exploitability"]
    return [f"exploitability.cvss_{k.lower()} is {ex.get('cvss_' + k.lower())} but vector has {m.get(k)}"
            for k in ("AV", "AC", "PR", "UI") if ex.get("cvss_" + k.lower()) != m.get(k)]


# ------------------------------------------------------------------ policy

def inputs_from_assessment(a: dict) -> PolicyInputs:
    """Rebuild the policy inputs from what the assessment recorded."""
    r = a["rationale"]
    vector = a["severity_vs_local_risk"]["technical_severity"].get("vector")
    kw = dict(
        conditions={c["id"]: c["result"] for c in r["applicability"]["conditions"]},
        decisive_tool_failure=any(t["tool"] in DECISIVE_TOOLS and t["result_status"] == "failed" for t in a["tool_trace"]),
        cvss_metrics=parse_cvss_vector(vector) if vector else None,
    )
    if r.get("likelihood"):
        f = r["likelihood"]["factors"]
        reach = f["reachability"]
        ea = f["exploit_activity"]
        kw.update(
            reachability=None if reach["defaulted"] else reach["score"],
            kev_listed=ea["kev_listed"],
            credible_in_the_wild=ea["credible_in_the_wild"],
            public_poc=ea["public_poc"],
            vendor_exploitation_likely=ea["vendor_exploitation_likely"],
        )
    if r.get("impact"):
        f = r["impact"]["factors"]
        rto = next((x for x in r["impact"]["adjustments"] if x["id"] == "ADJ-RTO"), None)
        kw.update(
            asset_criticality=f["asset_criticality"]["score"],
            blast_radius=f["blast_radius"]["score"],
            rto_hours=rto["input_value"] if rto and rto["input_status"] == "known" else None,
        )
    return PolicyInputs(**kw)


def _diff(path: str, expected, actual, out: list[str]) -> None:
    if expected != actual:
        out.append(f"{path}: policy gives {expected!r}, assessment has {actual!r}")


def check_policy(a: dict) -> list[str]:
    try:
        exp = evaluate(inputs_from_assessment(a))
    except (ValueError, KeyError, TypeError) as err:
        return [f"policy could not be applied: {err}"]
    r, d, out = a["rationale"], a["decision"], []

    for k in ("rating", "policy_rule_applied", "gate_reached"):
        _diff(f"decision.{k}", exp["decision"][k], d[k], out)
    prov = d.get("provisional")
    _diff("decision.provisional", exp["decision"]["provisional"],
          {k: prov[k] for k in ("rating", "policy_rule", "binding")} if prov else None, out)
    for k in ("status", "gate_1_outcome"):
        _diff(f"applicability.{k}", exp["applicability"][k], r["applicability"][k], out)
    _diff("gate_2_status", exp["gate_2_status"], r["gate_2_status"], out)

    for block in ("likelihood", "impact", "matrix_result"):
        e, got = exp[block], r.get(block)
        if (e is None) != (got is None):
            out.append(f"{block}: policy gives {'null' if e is None else 'a value'}, assessment has {'null' if got is None else 'a value'}")
            continue
        if e is None:
            continue
        if block == "matrix_result":
            for k, v in e.items():
                _diff(f"matrix_result.{k}", v, got[k], out)
            continue
        for fname, fexp in e["factors"].items():
            for k, v in fexp.items():
                _diff(f"{block}.factors.{fname}.{k}", v, got["factors"][fname][k], out)
        for k in e:
            if k not in ("factors", "adjustments"):
                _diff(f"{block}.{k}", e[k], got[k], out)
        if block == "impact":
            got_adj = {x["id"]: x for x in got["adjustments"]}
            for adj in e["adjustments"]:
                g = got_adj.get(adj["id"])
                if not g:
                    out.append(f"impact.adjustments: {adj['id']} missing")
                    continue
                for k in ("triggered", "effect", "binding", "input_status"):
                    _diff(f"impact.adjustments[{adj['id']}].{k}", adj[k], g[k], out)
    return out


# ------------------------------------------------------------------ entry point

def validate_assessment(a: dict, schema: dict) -> dict:
    results: list = []
    schema_problems = check_schema(a, schema)
    _check(results, "Output matches assessment_schema.json", schema_problems)
    if schema_problems:  # later checks assume a well-formed document
        return {"schema_valid": False, "checks": results}
    _check(results, "Every cited evidence_id exists and every evidence item is cited", check_evidence_refs(a))
    _check(results, "Every evidence item points to a call in tool_trace", check_tool_refs(a))
    _check(results, "Missing decisive facts are listed in unknowns[]", check_unknown_refs(a))
    _check(results, "Cached evidence has a fallback reason; environment evidence is labeled simulated", check_labels(a))
    _check(results, "Tool calls follow the tool contracts", check_tool_contracts(a))
    _check(results, "kev_listed matches the lookup_kev result", check_kev_matches_tool(a))
    _check(results, "Exploitability CVSS fields match the CVSS vector", check_cvss_consistency(a))
    _check(results, "Review Needed for conflicting evidence lists the conflicts", check_conflicts(a))
    _check(results, "Decision, scores and matrix match policy.py", check_policy(a))
    return {"schema_valid": True, "checks": results}


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("assessment", type=Path)
    ap.add_argument("--schema", type=Path, default=DEFAULT_SCHEMA)
    ap.add_argument("--write", action="store_true", help="store results in the assessment's validation block")
    args = ap.parse_args()

    a = json.loads(args.assessment.read_text())
    report = validate_assessment(a, json.loads(args.schema.read_text()))
    for c in report["checks"]:
        print(f"[{'PASS' if c['passed'] else 'FAIL'}] {c['check']}" + ("" if c["passed"] else f"\n       {c['detail']}"))
    if args.write:
        a["validation"] = report
        args.assessment.write_text(json.dumps(a, indent=2, ensure_ascii=False) + "\n")
    return 0 if all(c["passed"] for c in report["checks"]) else 1


if __name__ == "__main__":
    sys.exit(main())

"""Policy tests. The first four map to the Assignment 2 policy checks.

Baseline = the W01 / CVE-2026-69730 facts: internal reachability, network
unauthenticated RCE (AV:N/AC:L/PR:N/UI:N, C/I/A High), not in KEV, vendor
'Exploitation More Likely', critical Tier 0 asset, domain-wide blast radius,
RTO 4h. Expected values are set from the group's documented policy.
"""

import sys
from dataclasses import replace
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from policy import PolicyInputs, evaluate, exploitability_score  # noqa: E402

CVSS = {"AV": "N", "AC": "L", "PR": "N", "UI": "N", "C": "H", "I": "H", "A": "H"}


def baseline(**changes) -> PolicyInputs:
    base = PolicyInputs(
        conditions={"C1": "true", "C2": "true", "C3": "unknown"},
        reachability=1, cvss_metrics=CVSS,
        kev_listed=False, credible_in_the_wild=False, public_poc=None, vendor_exploitation_likely=True,
        asset_criticality=2, blast_radius=2, rto_hours=4,
    )
    return replace(base, **changes)


# ---------------------------------------------------------------- baseline run

def test_baseline_is_insufficient_evidence_with_provisional_high():
    r = evaluate(baseline())
    assert r["decision"]["rating"] == "Insufficient Evidence"
    assert r["decision"]["policy_rule_applied"] == "P-IE"
    assert r["decision"]["provisional"] == {"rating": "High", "policy_rule": "P-H-L4I2", "binding": False}
    assert r["gate_2_status"] == "provisional"


# ---------------------------------------------------------------- policy check 1: applicability change (impact held constant)

@pytest.mark.parametrize("c3, rating, rule", [
    ("true", "High", "P-H-L4I2"),   # a DC is below 10.0.20348.5622
    ("false", "Low", "P-NA"),       # all DCs patched
])
def test_applicability_change(c3, rating, rule):
    r = evaluate(baseline(conditions={"C1": "true", "C2": "true", "C3": c3}))
    assert (r["decision"]["rating"], r["decision"]["policy_rule_applied"]) == (rating, rule)


# ---------------------------------------------------------------- policy check 2: impact change (applicability held constant)

def test_impact_change():
    confirmed = {"C1": "true", "C2": "true", "C3": "true"}
    high = evaluate(baseline(conditions=confirmed))
    lower = evaluate(baseline(conditions=confirmed, asset_criticality=1, blast_radius=1, rto_hours=8))
    assert high["decision"]["policy_rule_applied"] == "P-H-L4I2"
    assert lower["decision"]["policy_rule_applied"] == "P-M-L4I1"
    assert lower["likelihood"] == high["likelihood"]  # only impact moved


# ---------------------------------------------------------------- policy check 3: missing / conflicting evidence

def test_missing_evidence_is_insufficient_evidence():
    r = evaluate(baseline())  # C3 unknown
    assert r["decision"]["rating"] == "Insufficient Evidence"


def test_conflicting_evidence_is_review_needed():
    r = evaluate(baseline(conditions={"C1": "true", "C2": "true", "C3": "conflicting"}))
    assert (r["decision"]["rating"], r["decision"]["policy_rule_applied"]) == ("Review Needed", "P-RV-C")
    assert r["likelihood"] is None  # no provisional rating on conflict


# ---------------------------------------------------------------- controlled failure

def test_decisive_tool_failure_is_review_needed():
    r = evaluate(baseline(decisive_tool_failure=True, cvss_metrics=None))
    assert (r["decision"]["rating"], r["decision"]["policy_rule_applied"]) == ("Review Needed", "P-RV-F")


def test_confirmed_false_wins_over_tool_failure():
    r = evaluate(baseline(conditions={"C1": "true", "C2": "false", "C3": "unknown"}, decisive_tool_failure=True))
    assert r["decision"]["policy_rule_applied"] == "P-NA"


# ---------------------------------------------------------------- likelihood rules

def test_kev_sets_exploit_activity_to_2():
    r = evaluate(baseline(conditions={"C1": "true", "C2": "true", "C3": "true"}, kev_listed=True))
    assert r["likelihood"]["factors"]["exploit_activity"]["score"] == 2
    assert r["likelihood"]["final_score"] == 5


def test_unknown_reachability_defaults_to_1():
    r = evaluate(baseline(reachability=None))
    assert r["likelihood"]["factors"]["reachability"] == {"score": 1, "defaulted": True}


def test_isolated_asset_caps_likelihood_at_1():
    r = evaluate(baseline(conditions={"C1": "true", "C2": "true", "C3": "true"}, reachability=0, kev_listed=True))
    assert r["likelihood"]["raw_sum"] == 4
    assert r["likelihood"]["final_score"] == 1
    assert r["likelihood"]["reachability_cap_applied"] is True


@pytest.mark.parametrize("metrics, score", [
    ({"AV": "L", "AC": "L", "PR": "N", "UI": "N"}, 0),
    ({"AV": "N", "AC": "H", "PR": "N", "UI": "N"}, 1),
    ({"AV": "A", "AC": "L", "PR": "N", "UI": "N"}, 2),
])
def test_exploitability(metrics, score):
    assert exploitability_score(metrics) == score


# ---------------------------------------------------------------- impact adjustments

def test_rto_adjustment_not_binding_at_max_impact():
    adj = {a["id"]: a for a in evaluate(baseline())["impact"]["adjustments"]}
    assert adj["ADJ-RTO"]["triggered"] and not adj["ADJ-RTO"]["binding"]


def test_rto_adjustment_binding_below_max():
    r = evaluate(baseline(asset_criticality=1, blast_radius=1, rto_hours=4))
    assert r["impact"]["final_score"] == 2
    assert {a["id"]: a for a in r["impact"]["adjustments"]}["ADJ-RTO"]["binding"]


def test_unknown_rto_makes_no_adjustment():
    adj = {a["id"]: a for a in evaluate(baseline(rto_hours=None))["impact"]["adjustments"]}
    assert adj["ADJ-RTO"]["input_status"] == "unknown" and not adj["ADJ-RTO"]["triggered"]


def test_low_cia_reduces_impact():
    low = {**CVSS, "C": "L", "I": "N", "A": "L"}
    r = evaluate(baseline(cvss_metrics=low, rto_hours=8))
    assert r["impact"]["final_score"] == 1


# ---------------------------------------------------------------- input guards

def test_invalid_condition_value_rejected():
    with pytest.raises(ValueError):
        PolicyInputs(conditions={"C1": "maybe"})


def test_confirmed_without_gate_2_inputs_raises():
    with pytest.raises(ValueError):
        evaluate(baseline(conditions={"C1": "true", "C2": "true", "C3": "true"}, cvss_metrics=None))

"""Validator tests: the example passes, and deliberately broken copies fail the right check."""

import copy
import json
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from validate import validate_assessment  # noqa: E402

SCHEMA = json.loads((ROOT / "assessment_schema.json").read_text())
EXAMPLE = json.loads((ROOT / "assessment_example_CVE-2026-69730_W01.json").read_text())


def failed_checks(a):
    report = validate_assessment(a, SCHEMA)
    return {c["check"] for c in report["checks"] if not c["passed"]}


def test_example_passes():
    assert failed_checks(EXAMPLE) == set()


def broken(fn):
    a = copy.deepcopy(EXAMPLE)
    fn(a)
    return failed_checks(a)


def _set_kev_true_but_score_1(a):
    a["rationale"]["likelihood"]["factors"]["exploit_activity"]["kev_listed"] = True


def _wrong_rating(a):
    a["decision"]["rating"] = "High"


def _cite_missing_evidence(a):
    a["rationale"]["applicability"]["conditions"][0]["evidence_ids"].append("E99")


def _cached_without_reason(a):
    next(e for e in a["evidence"] if e["retrieval_mode"] == "cached")["fallback_reason"] = None


def _env_evidence_labeled_live(a):
    next(e for e in a["evidence"] if e["source_type"] == "environment_snapshot")["retrieval_mode"] = "live"


def _env_search_without_query(a):
    del next(t for t in a["tool_trace"] if t["tool"] == "environment_search")["arguments"]["query"]


def _vuln_lookup_failed_but_not_review(a):
    next(t for t in a["tool_trace"] if t["tool"] == "lookup_vulnerability")["result_status"] = "failed"


def _bad_matrix(a):
    a["rationale"]["matrix_result"]["policy_rule"] = "P-M-L4I2"


def _missing_field(a):
    del a["action"]


@pytest.mark.parametrize("mutate, expected_check", [
    (_set_kev_true_but_score_1, "Decision, scores and matrix match policy.py"),
    (_wrong_rating, "Decision, scores and matrix match policy.py"),
    (_bad_matrix, "Decision, scores and matrix match policy.py"),
    (_vuln_lookup_failed_but_not_review, "Decision, scores and matrix match policy.py"),
    (_cite_missing_evidence, "Every cited evidence_id exists and every evidence item is cited"),
    (_cached_without_reason, "Cached evidence has a fallback reason; environment evidence is labeled simulated"),
    (_env_evidence_labeled_live, "Cached evidence has a fallback reason; environment evidence is labeled simulated"),
    (_env_search_without_query, "Tool calls follow the tool contracts"),
    (_missing_field, "Output matches assessment_schema.json"),
])
def test_broken_copies_fail(mutate, expected_check):
    assert expected_check in broken(mutate)

