346	      "items": {
347	        "type": "object",
348	        "required": [
349	          "evidence_id",
350	          "fact",
351	          "source_name",
352	          "source_type",
353	          "url_or_path",
354	          "locator",
355	          "retrieved_at",
356	          "retrieval_mode",
357	          "tool_call_id"
358	        ],
359	        "properties": {
360	          "evidence_id": {"type": "string", "pattern": "^E\\d+$"},
361	          "fact": {"type": "string", "minLength": 1},
362	          "source_name": {"type": "string"},
363	          "source_type": {
364	            "enum": [
365	              "cve_record",
