386	          },
387	          "published_date": {"type": ["string", "null"], "format": "date"},
388	          "last_modified_date": {"type": ["string", "null"], "format": "date"},
389	          "retrieved_at": {"type": "string", "format": "date-time"},
390	          "retrieval_mode": {"enum": ["live", "cached", "simulated"]},
391	          "fallback_reason": {"type": ["string", "null"]},
392	          "tool_call_id": {"type": "string", "pattern": "^T\\d+$"}
393	        }
394	      }
395	    },
396	    "assumptions": {
397	      "type": "array",
398	      "items": {
399	        "type": "object",
400	        "required": ["id", "statement", "reason", "affects"],
401	        "properties": {
402	          "id": {"type": "string", "pattern": "^A\\d+$"},
403	          "statement": {"type": "string"},
404	          "reason": {"type": "string"},
405	          "affects": {"type": "array", "items": {"type": "string"}}
406	        }
407	      }
408	    },
409	    "unknowns": {
410	      "type": "array",
