416	          "question": {"type": "string"},
417	          "decisive": {"type": "boolean"},
418	          "why_it_matters": {"type": "string"},
419	          "default_applied": {"type": "string"},
420	          "how_to_resolve": {"type": "string"}
421	        }
422	      }
423	    },
424	    "conflicts": {
425	      "type": "array",
426	      "items": {
427	        "type": "object",
428	        "required": ["id", "fact", "values", "evidence_ids", "resolution"],
429	        "properties": {
430	          "id": {"type": "string", "pattern": "^X\\d+$"},
431	          "fact": {"type": "string"},
432	          "values": {"type": "array", "items": {"type": "string"}, "minItems": 2},
433	          "evidence_ids": {"$ref": "#/$defs/evidence_ids"},
434	          "resolution": {"type": ["string", "null"]}
435	        }
