478	          "result_status",
479	          "mode",
480	          "attempts",
481	          "fallback_used",
482	          "evidence_ids",
483	          "error"
484	        ],
485	        "properties": {
486	          "call_id": {"type": "string", "pattern": "^T\\d+$"},
487	          "tool": {"enum": ["environment_search", "lookup_vulnerability", "lookup_kev", "tavily_search"]},
