493	            "description": "mixed = lookup_vulnerability merged a live and a cached source. null when the call failed with no data."
494	          },
495	          "attempts": {"type": "integer", "minimum": 1, "maximum": 2},
496	          "fallback_used": {"type": "boolean"},
497	          "result_summary": {"type": ["string", "null"]},
498	          "raw_output_path": {
499	            "type": ["string", "null"],
500	            "description": "Saved raw tool output for the run baseline."
501	          },
502	          "evidence_ids": {"$ref": "#/$defs/evidence_ids"},
503	          "error": {"type": ["string", "null"]}
504	        }
505	      }
506	    },
507	    "validation": {
508	      "type": "object",
