510	      "properties": {
511	        "schema_valid": {"type": "boolean"},
512	        "checks": {
513	          "type": "array",
514	          "items": {
515	            "type": "object",
516	            "required": ["check", "passed", "detail"],
517	            "properties": {
518	              "check": {"type": "string"},
519	              "passed": {"type": "boolean"},
520	              "detail": {"type": "string"}
521	            }
522	          }
523	        }
524	      },
525	      "description": "Written by validate.py --write."
526	    },
527	    "analyst_review": {
528	      "type": "object",
529	      "required": ["status", "reviewer", "reviewed_at", "citations_verified", "agrees_with_rating"],
530	      "properties": {
531	        "status": {"enum": ["pending", "approved", "changed", "rejected"]},
532	        "reviewer": {"type": ["string", "null"]},
533	        "reviewed_at": {"type": ["string", "null"], "format": "date-time"},
534	        "citations_verified": {"type": ["boolean", "null"]},
535	        "agrees_with_rating": {"type": ["boolean", "null"]},
536	        "group_consensus_rating": {"enum": ["High", "Medium", "Low", "Insufficient Evidence", "Review Needed", null]},
537	        "notes": {"type": ["string", "null"]}
538	      }
539	    }
540	  },
541	  "$defs": {
542	    "decision_value": {"enum": ["High", "Medium", "Low", "Insufficient Evidence", "Review Needed"]},
543	    "policy_rule": {"type": "string", "pattern": "^(P-NA|P-IE|P-RV-C|P-RV-F|P-[HML]-L[0-6]I[0-2])$"},
544	    "evidence_ids": {"type": "array", "items": {"type": "string", "pattern": "^E\\d+$"}},
