from tools.base import ToolOutput, receipt_of

BASE_METRICS = ("AV", "AC", "PR", "UI", "S", "C", "I", "A")
TEMPORAL_NAMES = {"E": "exploit_code_maturity", "RL": "remediation_level", "RC": "report_confidence"}


def _norm_product(name: str) -> str:
    """'Windows Server 2022 (Server Core installation)' -> 'windows_server_2022'."""
    name = re.sub(r"\(.*?\)", "", name).strip().lower()
    return re.sub(r"[\s\-]+", "_", name)


def _date(ts):
    return ts[:10] if ts else None


# ---------------------------------------------------------------- CVE record

def _from_cve(d: dict) -> dict:
    cna = d["containers"]["cna"]
    meta = d["cveMetadata"]
    out = {
        "title": cna.get("title"),
        "description": next((x["value"] for x in cna.get("descriptions", []) if x.get("lang", "").startswith("en")), None),
        "cwe": [x.get("cweId") for p in cna.get("problemTypes", []) for x in p.get("descriptions", []) if x.get("cweId")],
        "published": _date(meta.get("datePublished")),
        "last_modified": _date(meta.get("dateUpdated")),
        "references": [r["url"] for r in cna.get("references", [])],
        "cvss": None,
        "affected": [],
        "ssvc": None,
    }
    for m in cna.get("metrics", []):
        v = m.get("cvssV3_1") or m.get("cvssV3_0")
        if v:
            out["cvss"] = {"version": v["version"], "base_score": v["baseScore"], "base_severity": v["baseSeverity"].title(),
                           "vector": v["vectorString"], "source": cna.get("providerMetadata", {}).get("shortName", "CNA")}
            break
    for a in cna.get("affected", []):
        for ver in a.get("versions", []):
            if ver.get("status") == "affected":
                out["affected"].append({"product": a["product"], "version_start": ver.get("version"), "fixed_build": ver.get("lessThan")})
    for adp in d["containers"].get("adp", []):
        for m in adp.get("metrics", []):
            other = m.get("other", {})
            if other.get("type") == "ssvc":
                opts = {k: v for o in other["content"]["options"] for k, v in o.items()}
                out["ssvc"] = {"source": adp.get("title", "ADP"), "timestamp": other["content"].get("timestamp"), **opts}
    return out


# ---------------------------------------------------------------- NVD record

def _from_nvd(d: dict, cve_id: str) -> dict:
    cve = next(v["cve"] for v in d["vulnerabilities"] if v["cve"]["id"] == cve_id)
    metrics = cve.get("metrics", {})
    cvss_list = []
    for key in ("cvssMetricV31", "cvssMetricV30"):
        for m in metrics.get(key, []):
            c = m["cvssData"]
            cvss_list.append({"version": c["version"], "base_score": c["baseScore"], "base_severity": c["baseSeverity"].title(),
                              "vector": c["vectorString"], "source": m.get("source"), "type": m.get("type")})
    ranges = []
    for cfg in cve.get("configurations", []):
        for node in cfg.get("nodes", []):
            for cm in node.get("cpeMatch", []):
                if cm.get("vulnerable"):
                    ranges.append({"cpe_product": cm["criteria"].split(":")[4], "version_start": cm.get("versionStartIncluding"),
                                   "fixed_build": cm.get("versionEndExcluding")})
