        "description": next((x["value"] for x in cve.get("descriptions", []) if x.get("lang") == "en"), None),
        "cwe": [x["value"] for w in cve.get("weaknesses", []) for x in w.get("description", []) if x["value"].startswith("CWE-")],
        "nvd_status": cve.get("vulnStatus"),
        "published": _date(cve.get("published")),
        "last_modified": _date(cve.get("lastModified")),
        "cvss_all": cvss_list,
        "ranges": ranges,
    }


# ---------------------------------------------------------------- merge

def _conflicts(cve: dict | None, nvd: dict | None) -> list[str]:
    if not cve or not nvd:
        return []
    out = []
    if cve["cvss"]:
        cna_m = parse_cvss_vector(cve["cvss"]["vector"])
        for n in nvd["cvss_all"]:
            nm = parse_cvss_vector(n["vector"])
            diff = [k for k in BASE_METRICS if cna_m.get(k) != nm.get(k)]
            if diff:
                out.append(f"CVSS base metrics {diff} differ: CVE record {cve['cvss']['vector']} vs NVD ({n['source']}) {n['vector']}")
            elif cve["cvss"]["base_score"] != n["base_score"]:
                out.append(f"CVSS base score differs: CVE record {cve['cvss']['base_score']} vs NVD ({n['source']}) {n['base_score']}")
    nvd_fixed = {}
    for r in nvd["ranges"]:
        if r["fixed_build"]:
            nvd_fixed.setdefault(r["cpe_product"], set()).add(r["fixed_build"])
    for a in cve["affected"]:
        p = _norm_product(a["product"])
        if p in nvd_fixed and a["fixed_build"] not in nvd_fixed[p]:
            out.append(f"Fixed build for {a['product']} differs: CVE record {a['fixed_build']} vs NVD {sorted(nvd_fixed[p])}")
    return sorted(set(out))


def _pick_cvss(cve: dict | None, nvd: dict | None) -> dict | None:
    """NVD Primary score if NVD scored it; otherwise the CNA score (CVE record, then NVD Secondary)."""
    if nvd:
        primary = [c for c in nvd["cvss_all"] if c.get("type") == "Primary"]
        if primary:
            c = primary[0]
            return {**c, "source": f"NVD ({c['source']})", "locator": "nvd:metrics.cvssMetricV31[type=Primary]"}
    if cve and cve["cvss"]:
        return {**cve["cvss"], "source": f"{cve['cvss']['source']} (CNA) via CVE record", "locator": "cve:containers.cna.metrics[0].cvssV3_1"}
    if nvd and nvd["cvss_all"]:
        c = nvd["cvss_all"][0]
        return {**c, "source": f"{c['source']} via NVD", "locator": "nvd:metrics.cvssMetricV31[0]"}
    return None


def run(args: dict, settings: dict) -> ToolOutput:
    cve_id = args["cve_id"]
    cve_res, nvd_res = fetch_cve(cve_id, settings), fetch_nvd(cve_id, settings)
    receipts = [receipt_of(cve_res), receipt_of(nvd_res)]
    cve = _from_cve(cve_res.data) if cve_res.ok else None
    nvd = _from_nvd(nvd_res.data, cve_id) if nvd_res.ok else None
    attempts = max(cve_res.attempts, nvd_res.attempts, 1)
    fallback_used = any(r.mode == "cached" or r.status == "failed" for r in (cve_res, nvd_res))

    if not cve and not nvd:
        status = "not_found" if "failed" not in (cve_res.status, nvd_res.status) else "failed"
        err = None if status == "not_found" else f"CVE: {cve_res.error or cve_res.status}; NVD: {nvd_res.error or nvd_res.status}"
        result = {"status": status, "cve_id": cve_id, "sources": [_src(cve_res, settings, cve_id), _src(nvd_res, settings, cve_id)]}
        return ToolOutput(result, status, None, attempts, fallback_used, f"{cve_id}: {status}", err, receipts)

    modes = {r.mode for r in (cve_res, nvd_res) if r.ok}
    mode = modes.pop() if len(modes) == 1 else "mixed"
    cvss = _pick_cvss(cve, nvd)
    if cvss:
        m = parse_cvss_vector(cvss["vector"])
        cvss["metrics"] = {k: m.get(k) for k in BASE_METRICS}
        cvss["temporal"] = {TEMPORAL_NAMES[k]: m[k] for k in TEMPORAL_NAMES if k in m} or None
    notes = [f"{r.source.upper()} {r.status}: {r.error or 'no record'}" for r in (cve_res, nvd_res) if not r.ok]
    result = {
        "status": "found",
        "cve_id": cve_id,
        "title": cve["title"] if cve else None,
        "description": (cve or nvd)["description"],
        "cwe": sorted(set((cve or {}).get("cwe", []) + (nvd or {}).get("cwe", []))),
        "nvd_status": nvd["nvd_status"] if nvd else None,
        "cvss": cvss,
        "affected": cve["affected"] if cve else [
            {"product": r["cpe_product"], "version_start": r["version_start"], "fixed_build": r["fixed_build"]} for r in nvd["ranges"]],
        "ssvc": cve["ssvc"] if cve else None,
        "dates": {"cve_published": cve and cve["published"], "cve_last_modified": cve and cve["last_modified"],
                  "nvd_published": nvd and nvd["published"], "nvd_last_modified": nvd and nvd["last_modified"]},
        "references": cve["references"] if cve else [],
        "conflicts": _conflicts(cve, nvd),
        "notes": notes,
        "sources": [_src(cve_res, settings, cve_id), _src(nvd_res, settings, cve_id)],
        "locators": {
            "description": "cve:containers.cna.descriptions[0]" if cve else "nvd:descriptions[lang=en]",
            "cvss": cvss["locator"] if cvss else None,
            "affected": "cve:containers.cna.affected[product=...].versions[0]" if cve else "nvd:configurations[0].nodes[0].cpeMatch",
            "ssvc": "cve:containers.adp[title='CISA ADP Vulnrichment'].metrics[0].other" if cve else None,
        },
    }
    summary = (f"{cve_id}: CVE {cve_res.mode or cve_res.status}, NVD {nvd_res.mode or nvd_res.status}; "
               f"CVSS {cvss['base_score'] if cvss else 'n/a'}; {len(result['conflicts'])} conflict(s)")
    return ToolOutput(result, "found", mode, attempts, fallback_used, summary, None, receipts,
                      source_raw={"cve": cve_res.data, "nvd": nvd_res.data})


def _src(res, settings: dict, cve_id: str) -> dict:
    conf = settings["sources"][res.source]
    return {"name": "CVE" if res.source == "cve" else "NVD", "url": conf["display_url"].format(cve_id=cve_id),
            "retrieved_at": res.retrieved_at, "mode": res.mode, "status": res.status, "fallback_reason": res.fallback_reason}

