        content = item if isinstance(item, str) else json.dumps(item)
        try:
            parsed = json.loads(content)
        except json.JSONDecodeError as err:
            return ModelReply(content=content), None, f"reply is not valid JSON: {err}"
        return ModelReply(content=content), parsed, None


