    for token in re.findall(r"[^.\[\]]+|\[[^\]]*\]", path):
        if obj is None:
            return None
        if token.startswith("["):
            inner = token[1:-1]
            if inner.isdigit():
                obj = obj[int(inner)] if isinstance(obj, list) and int(inner) < len(obj) else None
            elif "=" in inner:
